+// RF-004: descuento opcional en porcentaje (0 a 100) por línea, redondeado al centavo.
+function totalLinea(item) {
+  const bruto = item.cantidad * item.precioUnitarioCentavos;
+  const descuento = item.descuentoPorcentaje ?? 0;
+  if (typeof descuento !== "number" || !Number.isFinite(descuento) || descuento < 0 || descuento > 100)
+    throw new RangeError("Descuento inválido: debe estar entre 0 y 100");
+  return Math.round((bruto * (100 - descuento)) / 100);
+}
+
