diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..8d83cf0 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,28 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+test("RF-004: descuento por línea en porcentaje, redondeado al centavo", () => {
+  const f = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 }]);
+  assert.equal(f.totalCentavos, 1800);
+  assert.deepEqual(f, { totalCentavos: 1800, ivaCentavos: 234, netoCentavos: 1566 });
+  // redondeo al centavo: 333 con 50 % = 166,5 -> 167
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 333, descuentoPorcentaje: 50 }]).totalCentavos, 167);
+  // 0 y 100 son válidos; sin descuento equivale a 0
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 500, descuentoPorcentaje: 100 }]).totalCentavos, 0);
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 500, descuentoPorcentaje: 0 }]).totalCentavos, 500);
+  // el descuento se aplica por línea
+  assert.equal(calcularFactura([
+    { cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 },
+    { cantidad: 1, precioUnitarioCentavos: 1000 },
+  ]).totalCentavos, 1900);
+});
+
+test("RF-004: un descuento fuera de 0–100 se rechaza", () => {
+  for (const d of [-1, 101, NaN, "10", Infinity]) {
+    assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 1000, descuentoPorcentaje: d }]), RangeError);
+  }
+});
